// GENERATED by scripts/sync-functions-shared.mjs from src/. Do not edit.
// Reads facility capacities (rooms, beds, bags a day, fuel tank litres, LPG tonnes,
// seats, housing units, floor area in m²) out of screening and site-verification records, so fee
// estimates can use the facility's real size. Pure functions: used by the app and
// copied into functions/shared for the assistant (see scripts/sync-functions-shared.mjs).

const WORDS = {
  one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10,
  eleven: 11, twelve: 12, thirteen: 13, fourteen: 14, fifteen: 15, sixteen: 16, seventeen: 17,
  eighteen: 18, nineteen: 19, twenty: 20, thirty: 30, forty: 40, fifty: 50, sixty: 60,
  seventy: 70, eighty: 80, ninety: 90, hundred: 100,
}

export function toMs(v) {
  if (v == null || v === '') return null
  if (typeof v === 'number') return v
  if (typeof v.toMillis === 'function') return v.toMillis()
  if (typeof v.seconds === 'number') return v.seconds * 1000
  if (typeof v._seconds === 'number') return v._seconds * 1000
  const t = new Date(v).getTime()
  return Number.isNaN(t) ? null : t
}

// "Nine (9)" -> 9, "Twenty-two (22)" -> 22, "Six" -> 6, "45,000L" -> 45000
export function parseCount(text) {
  if (text == null) return null
  if (typeof text === 'number') return Number.isFinite(text) ? text : null
  const s = String(text).toLowerCase()
  const paren = s.match(/\((\d[\d,]*)\)/)
  if (paren) return Number(paren[1].replace(/,/g, ''))
  const digits = s.match(/\d[\d,]*(?:\.\d+)?/)
  if (digits) return Number(digits[0].replace(/,/g, ''))
  const words = s.match(/\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)(?:[\s-]+(one|two|three|four|five|six|seven|eight|nine))?\b/)
  if (words) return WORDS[words[1]] + (words[2] ? WORDS[words[2]] : 0)
  return null
}

// Fuel tank text: "2 tanks - 45000 each" -> 90000, "2 - 2800 and 13500" -> 16300,
// "1*27,000" -> 27000, "1 - 20000, 1 - 20500" -> 40500, "35,000L" -> 35000.
export function parseTankLitres(text) {
  if (text == null || text === '') return null
  const s = String(text).toLowerCase().replace(/(\d),(\d{3})/g, '$1$2')
  const nums = (s.match(/\d+(?:\.\d+)?/g) || []).map(Number)
  const big = nums.filter((n) => n >= 500)
  if (!big.length) return null
  if (/each/.test(s)) {
    const count = nums.find((n) => n < 500 && n > 0) ?? 1
    return count * big[0]
  }
  return big.reduce((a, b) => a + b, 0)
}

// Lines of a free-text "Capacity" answer, e.g. "Rooms - 20\nCar park - 10".
function capacityLines(text) {
  return String(text ?? '').split(/\n|;|,(?!\d{3})/).map((l) => l.trim()).filter(Boolean)
}

const TEXT_PATTERNS = [
  { key: 'rooms', re: /\brooms?\b/ },
  { key: 'beds', re: /\bbeds?\b/ },
  { key: 'bags_per_day', re: /\bbags?\b/ },
  { key: 'boxes_per_day', re: /\bbox(es)?\b/ },
  { key: 'seats', re: /seat|sitting|auditor/ },
  { key: 'housing_units', re: /apartments?\b|flats?\b|housing units?/ },
]

function fromCapacityText(text) {
  const out = {}
  const all = String(text ?? '')
  if (/\b\d[\d,]*\s*-?\s*seater\b/i.test(all)) out.seats = parseCount(all.match(/\d[\d,]*\s*-?\s*seater/i)[0])
  for (const line of capacityLines(all)) {
    const l = line.toLowerCase()
    if (/car\s*park|parking|washroom|toilet|gen\s*set|air\s*con|staff/.test(l)) continue
    for (const { key, re } of TEXT_PATTERNS) {
      if (out[key] != null || !re.test(l)) continue
      const n = parseCount(l)
      if (n != null && n > 0) out[key] = n
    }
    if (out.litres == null && /\b(diesel|petrol|kerosene|premix)\b/.test(l)) {
      const n = parseTankLitres(l)
      if (n) out.litres = (out.litres ?? 0) + n
    }
  }
  // Diesel and petrol on separate lines both count.
  const fuel = capacityLines(all).filter((l) => /\b(diesel|petrol|kerosene|premix)\b/i.test(l))
  if (fuel.length > 1) out.litres = fuel.reduce((s, l) => s + (parseTankLitres(l) ?? 0), 0) || out.litres
  return out
}

// Total floor area in m² written in free text; null when none is given.
export function floorArea(text) {
  if (!text) return null
  const s = String(text).toLowerCase().replace(/(\d),(\d{3})/g, '$1$2')
  let total = 0
  for (const m of s.matchAll(/(\d+(?:\.\d+)?)\s*(?:m2|m²|sq\.?\s?m\b|sqm|square met\w*)(\s*each)?(?:\D{0,12}?(?:x|×|\*)\s*(\d+))?/g)) {
    const v = Number(m[1]) * (m[3] ? Number(m[3]) : 1)
    if (v > 0) total += v
  }
  return total > 0 ? Math.round(total) : null
}

// Capacities from one record (a screening, site verification, or a field report's
// embedded screening). Returns { rooms: 20, litres: 90000, ... }.
export function capacitiesFromRecord(rec) {
  if (!rec || typeof rec !== 'object') return {}
  const out = {}
  const set = (k, v) => { if (v != null && Number.isFinite(v) && v > 0 && out[k] == null) out[k] = v }

  set('rooms', parseCount(rec.num_rooms))
  set('beds', parseCount(rec.num_beds))

  const prod = String(rec.production_capacity ?? '')
  if (prod) {
    const n = parseCount(prod)
    const perMonth = /month/i.test(prod)
    const perYear = /year|annum/i.test(prod)
    if (n && !perYear) {
      if (/box/i.test(prod)) set('boxes_per_day', perMonth ? Math.round(n / 26) : n)
      else if (/bag/i.test(prod)) set('bags_per_day', perMonth ? Math.round(n / 26) : n)
      else if (!perMonth) set('production', n) // unit not written; the fee rule decides what it means
    }
  }

  const tankKeys = ['petrol_tank_count_capacity', 'diesel_tank_count_capacity', 'kerosene_tank_count_capacity']
  const tankText = tankKeys.map((k) => rec[k]).filter(Boolean)
  if (tankText.length) set('litres', tankText.reduce((s, t) => s + (parseTankLitres(t) ?? 0), 0) || null)

  if (rec.tank_count_capacity) {
    const t = String(rec.tank_count_capacity)
    if (/ton/i.test(t)) set('tonnes', parseCount(t.replace(/^\s*\d+\s*[*x×]\s*/i, '')))
    else {
      const l = parseTankLitres(t)
      // LPG tanks recorded in kg/litres: 1 tonne of LPG is roughly 1,960 litres.
      if (l) set('tonnes', Math.round((l / 1960) * 10) / 10)
    }
  }

  // Floor area for offices, shops and warehouses: "120 m2", "30 sq m each x 4".
  for (const t of [rec.capacity, rec.facility_capacity, rec.components, rec.screening?.capacity, rec.screening?.components]) {
    const area = floorArea(t)
    if (area) { set('floor_area', area); break }
  }

  const textSources = [rec.capacity, rec.facility_capacity, rec.screening?.capacity]
  for (const t of textSources) {
    if (!t) continue
    const found = fromCapacityText(t)
    for (const [k, v] of Object.entries(found)) set(k, v)
  }
  return out
}

const KIND_LABEL = {
  site_verifications: 'site verification',
  screenings: 'screening',
  field_reports: 'field report screening',
}

// All capacities for one facility, newest record first wins.
// records: [{ kind: 'screenings'|'site_verifications'|'field_reports', data, dateMs }]
export function facilityCapacities(records) {
  const sorted = [...records].sort((a, b) => (b.dateMs ?? 0) - (a.dateMs ?? 0))
  const out = {}
  for (const r of sorted) {
    const caps = capacitiesFromRecord(r.kind === 'field_reports' ? r.data?.screening : r.data)
    for (const [k, v] of Object.entries(caps)) {
      if (out[k]) continue
      out[k] = { value: v, source: KIND_LABEL[r.kind] ?? r.kind, dateMs: r.dateMs ?? null }
    }
  }
  return out
}

// { fileNumber: capacities } for every facility, from flat record lists.
// Each record needs a fileNumber (field reports use assigned_file_number).
export function buildCapacityIndex({ screenings = [], siteVerifications = [], fieldReports = [] }) {
  const byFile = new Map()
  const push = (fileNumber, rec) => {
    if (!fileNumber) return
    if (!byFile.has(fileNumber)) byFile.set(fileNumber, [])
    byFile.get(fileNumber).push(rec)
  }
  screenings.forEach((d) => push(d.fileNumber, { kind: 'screenings', data: d, dateMs: toMs(d.date) ?? toMs(d.created_at) }))
  siteVerifications.forEach((d) => push(d.fileNumber, { kind: 'site_verifications', data: d, dateMs: toMs(d.date) ?? toMs(d.created_at) }))
  fieldReports.filter((d) => d.screening).forEach((d) => push(d.assigned_file_number, { kind: 'field_reports', data: d, dateMs: toMs(d.date) ?? toMs(d.created_at) }))
  const index = {}
  for (const [fileNumber, recs] of byFile) {
    const caps = facilityCapacities(recs)
    if (Object.keys(caps).length) index[fileNumber] = caps
  }
  return index
}
